import { useRef, useState } from 'preact/hooks';
import { Page, Field, Button, Notice, Empty, Loading, useLoad } from '../../components/ui.jsx';
import { useIssuePages, PageMore } from './issue-controls.jsx';
import { usePlanningAction, PlanningRefresh } from './planning-controls.jsx';
import { formatBytes, uploadProgress, validateUpload, uploadAttachment } from './attachment-state.js';
export function AttachmentsPanel(props) { return <AttachmentResource key={props.issueId} {...props} />; }
function AttachmentResource({ api, issueId }) {
  const [query, setQuery] = useState('');
  const route = '/issues/' + encodeURIComponent(issueId) + '/attachments';
  const attachments = useIssuePages(api, route + '?q=' + encodeURIComponent(query));
  const access = useLoad(() => api.get(route + '?limit=1'), [issueId]);
  const [file, setFile] = useState(null);
  const [progress, setProgress] = useState(null);
  const input = useRef(null);
  const action = usePlanningAction();
  const canWrite = access.data?.permissions?.write && !access.error;
  function refresh() { attachments.reload(); access.reload(); }
  async function upload(event) {
    event.preventDefault();
    if (!canWrite) return;
    const problem = validateUpload(file, access.data?.maxUploadBytes ?? 0);
    if (problem) { action.setError(new Error(problem)); return; }
    const selected = file;
    setProgress({ loaded: 0, total: selected.size });
    await action.run(operation => uploadAttachment({ issueId, file: selected, signal: operation.signal,
      onProgress(value) { if (operation.current()) setProgress(value); }
    }), result => {
      action.setNotice(result.attachment.name + ' uploaded: ' + formatBytes(result.attachment.size) + ', SHA-256 ' + result.attachment.sha256);
      setFile(null); setProgress(null); if (input.current) input.current.value = ''; refresh();
    });
  }
  async function remove(attachment) {
    if (!canWrite || !globalThis.confirm('Delete attachment ' + attachment.name + '?')) return;
    await action.run(() => api.delete('/attachments/' + attachment.id), () => {
      action.setNotice(attachment.name + ' deleted'); refresh();
    });
  }
  return <section className="panel attachments-panel" data-attachment-issue={issueId}><h2>Attachments</h2>
    <PlanningRefresh busy={action.busy} onRefresh={refresh} />
    <Notice error={action.error ?? attachments.error ?? access.error} /><Notice>{action.notice}</Notice>
    {action.error && <Button type="button" onClick={refresh}>Check saved attachments and access</Button>}
    <Field label="Find attachments"><input type="search" value={query} onInput={event => setQuery(event.currentTarget.value)} /></Field>
    {attachments.loading ? <Loading /> : !attachments.items.length ? <Empty>No attachments match this view.</Empty> : <ul className="attachments-list">
      {attachments.items.map(attachment => <li key={attachment.id}>
        <div><a href={attachment.downloadUrl} download={attachment.name}>{attachment.name}</a>
          <p>{formatBytes(attachment.size)} · {attachment.mediaType} · {new Date(attachment.createdAt).toLocaleString()}</p>
          <details><summary>SHA-256 integrity digest</summary><code className="digest">{attachment.sha256}</code></details>
        </div>
        {canWrite && <Button busy={action.busy} onClick={() => remove(attachment)}>Delete {attachment.name}</Button>}
      </li>)}
    </ul>}
    <PageMore list={attachments} label="attachments" />
    {!access.loading && !canWrite && <Notice>Uploads and deletion are unavailable with current attachment permissions or while this project is archived. Downloads remain subject to current project access.</Notice>}
    {canWrite && <form onSubmit={upload}>
      <p>Maximum upload: {formatBytes(access.data.maxUploadBytes)}. Bytes are streamed privately and hashed by the server.</p>
      <Field label="Attachment file"><input type="file" ref={input} disabled={action.busy} onChange={event => { setFile(event.currentTarget.files[0] ?? null); setProgress(null); action.setError(null); action.setNotice(''); }} /></Field>
      {file && <p>{file.name} · {formatBytes(file.size)}</p>}
      {progress && <div role="status"><progress max="100" value={uploadProgress(progress.loaded, progress.total)} aria-label="Attachment upload progress" /> {uploadProgress(progress.loaded, progress.total)}% · {formatBytes(progress.loaded)} sent for {file?.name}</div>}
      <Button busy={action.busy} disabled={!file || access.loading} type="submit">Upload attachment</Button>
      {action.busy && progress && <Button type="button" onClick={action.cancel}>Cancel upload</Button>}
    </form>}
  </section>;
}
export function IssueAttachmentsPage(props) { return <AttachmentPage key={props.params.issueId} {...props} />; }
