import { toggleSelection, destinationAt, moveBody, bulkChanges } from './board-state.js';
export function BoardPage(props) { return <BoardView key={props.params.projectId} {...props} />; }
function BoardView({ api, params }) {
  const projectId = params.projectId;
  const [query, setQuery] = useState('');
  const [assigneeFilter, setAssigneeFilter] = useState('');
  const board = useLoad(() => api.get('/projects/' + projectId + '/board?q=' + encodeURIComponent(query) + '&assigneeId=' + encodeURIComponent(assigneeFilter)), [projectId, query, assigneeFilter]);
  const [selected, setSelected] = useState(new Set());
  const action = usePlanningAction();
  const { busy, error, notice } = action;
  const [draggingId, setDraggingId] = useState(null);
  const [targetStatus, setTargetStatus] = useState(null);
  const drag = useRef(null);
  const suppressClickUntil = useRef(0);
  const [bulkStatus, setBulkStatus] = useState('');
  const [bulkAssignee, setBulkAssignee] = useState('');
  const [bulkLabels, setBulkLabels] = useState([]);
  const [labelsMode, setLabelsMode] = useState('unchanged');
  const canWrite = board.data?.permissions.write && !board.data?.project.archived;
  async function persistMove(issueId, destination) {
    if (!destination || !canWrite) return;
    if (busy || !board.data.columns.some(column => column.issues.some(issue => issue.id === issueId))) return;
    await action.run(() => api.post('/issues/' + issueId + '/move', moveBody(destination, issueId)), result => {
      action.setNotice(result.issue.key + ' moved to ' + result.issue.statusName);
      setSelected(new Set()); board.reload();
    });
  }

  useEffect(() => {
    function pointerMove(event) {
      const current = drag.current;
      if (!current) return;
      if (Math.abs(event.clientX - current.x) + Math.abs(event.clientY - current.y) > 5) {
        current.moved = true;
        setDraggingId(current.issueId);
        setTargetStatus(destinationAt(document, event.clientX, event.clientY)?.statusId ?? null);
        event.preventDefault();
      }
    }
    function pointerUp(event) {
      const current = drag.current;
      drag.current = null;
      setDraggingId(null); setTargetStatus(null);
      if (current?.moved) {
        suppressClickUntil.current = Date.now() + 500;
        persistMove(current.issueId, destinationAt(document, event.clientX, event.clientY));
      }
    }
    function cancel() {
      const id = drag.current?.issueId;
      drag.current = null; setDraggingId(null); setTargetStatus(null);
      if (id) { suppressClickUntil.current = Date.now() + 500; document.querySelector('[data-testid="board-card-' + id + '"]')?.focus(); }
    }
    function key(event) { if (event.key === 'Escape') cancel(); }
    window.addEventListener('keydown', key);
    window.addEventListener('pointercancel', cancel);
    window.addEventListener('blur', cancel);
    window.addEventListener('pointermove', pointerMove, { passive: false });
    window.addEventListener('pointerup', pointerUp);
    return () => {
      cancel();
      window.removeEventListener('keydown', key);
      window.removeEventListener('pointercancel', cancel);
      window.removeEventListener('blur', cancel);
      window.removeEventListener('pointermove', pointerMove);
      window.removeEventListener('pointerup', pointerUp);
    };
  }, [canWrite, projectId, busy, board.data]);
  async function bulkEdit(event) {
    event.preventDefault();
    const body = bulkChanges({ statusId: bulkStatus, assigneeId: bulkAssignee, labelsMode, labelIds: bulkLabels });
    const preview = bulkPreview(selectedBoardIssues(board.data.columns, selected), body);
    if (!preview.valid) { action.setError(new Error('Select visible issues and at least one field change.')); return; }
    if (preview.destructive && !globalThis.confirm('Apply to ' + preview.ids.length + ' visible issues: ' + preview.summary + '? Existing values will be replaced.')) return;
    await action.run(() => api.post('/projects/' + projectId + '/issues/bulk', { issueIds: preview.ids, ...body }), result => {
      action.setNotice(result.count + ' issues updated'); setSelected(new Set()); board.reload();
    });
  }
  function filterChange(setter, value) { setSelected(new Set()); drag.current = null; setDraggingId(null); setTargetStatus(null); setter(value); }

  function beginPointer(event, issueId) {
    if (!canWrite || busy || event.button !== 0 || event.target.closest('input,button,select')) return;
    drag.current = { issueId, x: event.clientX, y: event.clientY, moved: false };
  }
  function startNative(event, issueId) {
    if (!canWrite || busy) { event.preventDefault(); return; }
    drag.current = { issueId, native: true };
    event.dataTransfer.setData('text/plain', issueId);
    event.dataTransfer.effectAllowed = 'move';
    setDraggingId(issueId);
  }
  function nativeDrop(event, statusId) {
    event.preventDefault();
    const rawId = event.dataTransfer.getData('text/plain');
    const issueId = drag.current?.native && drag.current.issueId === rawId ? rawId : null;
    drag.current = null;
    const target = event.target.closest('[data-issue-id]');
    setDraggingId(null); setTargetStatus(null);
    if (issueId) persistMove(issueId, { statusId, beforeId: target?.dataset.issueId });
  }
  if (board.error && !board.data) return <Notice error={board.error} />;
  if (!board.data || board.data.project.id !== projectId) return <Loading />;
  const project = board.data.project;
  const visibleSelection = selectedBoardIssues(board.data.columns, selected);
  const preview = bulkPreview(visibleSelection, bulkChanges({ statusId: bulkStatus, assigneeId: bulkAssignee, labelsMode, labelIds: bulkLabels }));
  return <Page title={project.name + ' board'} actions={<a href={'#/projects/' + projectId + '/issues'}>Create or edit issues</a>}>
    <ProjectLinks projectId={projectId} />
    <PlanningRefresh busy={busy} selected={selected.size > 0} onRefresh={() => { setSelected(new Set()); board.reload(); }} />
    <Notice error={error ?? board.error} /><Notice>{notice}</Notice>
    {project.archived && <Notice>This project is archived. Restore it to move or edit work.</Notice>}
    <div className="filters">
      <Field label="Find issues"><input type="search" value={query} placeholder="Key or title" onInput={event => filterChange(setQuery, event.currentTarget.value)} /></Field>
      <WorkPicker api={api} project={project} type="users" label="Filter by assignee" value={assigneeFilter} onChange={value => filterChange(setAssigneeFilter, value)} />
      <span role="status">{selected.size} selected</span>
      {selected.size > 0 && <Button onClick={() => setSelected(new Set())}>Clear selection</Button>}
    </div>
    {canWrite && selected.size > 0 && <form className="bulk-editor panel" onSubmit={bulkEdit}>
      <h2>Bulk edit {selected.size} issues</h2>
      <Field label="Status"><select value={bulkStatus} onChange={event => setBulkStatus(event.currentTarget.value)}>
        <option value="">Keep status</option>{project.statuses.map(status => <option value={status.id}>{status.name}</option>)}
      </select></Field>
      <Field label="Assignee action"><select value={bulkAssignee === '__unassigned' ? 'clear' : bulkAssignee ? 'assign' : 'keep'} onChange={event => setBulkAssignee(event.currentTarget.value === 'clear' ? '__unassigned' : '')}><option value="keep">Keep assignee</option><option value="clear">Clear assignees</option><option value="assign">Choose person below</option></select></Field>
      <WorkPicker api={api} project={project} type="users" permission="issue:write" label="Assign selected issues" value={bulkAssignee === '__unassigned' ? '' : bulkAssignee} onChange={setBulkAssignee} />
      <Field label="Label action"><select value={labelsMode} onChange={event => setLabelsMode(event.currentTarget.value)}>
        <option value="unchanged">Keep labels</option><option value="replace">Replace labels</option><option value="add">Add labels</option><option value="remove">Remove labels</option>
      </select></Field>
      {labelsMode !== 'unchanged' && <LabelSelection api={api} project={project} value={bulkLabels} onChange={setBulkLabels} />}
      <p role="status">Current visible selection: {visibleSelection.map(issue => issue.key + ' · ' + issue.title).join('; ') || 'None'}. Planned changes: {preview.summary}.</p>
      <Button busy={busy} disabled={!preview.valid || board.loading} type="submit">Apply to selected issues</Button>
    </form>}
    <p className="board-help">Drag a card into a column or onto another card to place it first. Keyboard users can use each card’s move menu. Select cards for an atomic bulk edit.</p>
    <div className="kanban" aria-busy={busy}>
      {board.data.columns.map(({ status, issues }) => <section key={status.id} data-status-id={status.id} data-testid={'board-column-' + status.id}
        className={'kanban-column ' + (targetStatus === status.id ? 'drop-target' : '')}
        onDragOver={event => { if (canWrite) { event.preventDefault(); setTargetStatus(status.id); } }}
        onDrop={event => nativeDrop(event, status.id)}>
        <header><h2>{status.name}</h2><span>{issues.length}</span></header>
        {issues.length === 0 && <Empty>Drop an issue here</Empty>}
        {issues.map((issue, index) => <article key={issue.id} data-issue-id={issue.id} data-testid={'board-card-' + issue.id}
          tabIndex="-1" draggable={Boolean(canWrite && !busy)} onDragStart={event => startNative(event, issue.id)}
          onDragEnd={() => { drag.current = null; setDraggingId(null); setTargetStatus(null); }}
          onPointerDown={event => beginPointer(event, issue.id)}
          className={'kanban-card ' + (draggingId === issue.id ? 'dragging' : '')}>
          <div className="card-top"><small>{issue.key}</small>{canWrite && <input type="checkbox" aria-label={'Select ' + issue.key} checked={selected.has(issue.id)} onChange={() => setSelected(toggleSelection(selected, issue.id))} />}</div>
          <a href={'#/issues/' + issue.id} onClick={event => { if (Date.now() < suppressClickUntil.current || draggingId) event.preventDefault(); }}>{issue.title}</a>
          <p>{issue.assignee?.name ?? 'Unassigned'}{issue.estimate != null ? ' · ' + issue.estimate + ' points' : ''}</p>
          <div className="issue-labels">{issue.labels.map(label => <span style={{ borderColor: label.color }}>{label.name}</span>)}</div>
          {issue.dueDate && <small>Due {issue.dueDate}</small>}
          {canWrite && <div className="card-order-actions">
            <Button disabled={busy || index === 0} aria-label={'Move ' + issue.key + ' earlier'} onClick={() => persistMove(issue.id, { statusId: status.id, beforeId: issues[index - 1].id })}>Move up</Button>
            <Button disabled={busy || index === issues.length - 1} aria-label={'Move ' + issue.key + ' later'} onClick={() => persistMove(issue.id, { statusId: status.id, afterId: issues[index + 1].id })}>Move down</Button>
          </div>}
          {canWrite && <Field label={'Move ' + issue.key}><select value={issue.statusId} disabled={busy} onChange={event => persistMove(issue.id, { statusId: event.currentTarget.value })}>
            {project.statuses.map(status => <option value={status.id}>{status.name}</option>)}
          </select></Field>}
        </article>)}
      </section>)}
    </div>
  </Page>;
}

export function createPlanningScope() {
  let generation = 0;
  let active = null;
  let disposed = false;
  return {
    begin() {
      if (disposed || active) return null;
      const controller = new AbortController();
      const ticket = ++generation;
      const operation = {
        signal: controller.signal,
        current: () => !disposed && ticket === generation && active === operation,
        finish() { if (active === operation) active = null; },
        cancel() { controller.abort(); }
      };
      active = operation;
      return operation;
    },
    cancel() { active?.cancel(); },
    dispose() { disposed = true; generation++; active?.cancel(); active = null; }
  };
}
export function selectedBoardIssues(columns, selected) {
  return columns.flatMap(column => column.issues).filter(issue => selected.has(issue.id));
}
export function bulkPreview(issues, changes) {
  const edits = [];
  if (changes.changes.statusId) edits.push('change status');
  if (changes.changes.assigneeId !== undefined) edits.push(changes.changes.assigneeId === null ? 'clear assignees' : 'assign a person');
  if (changes.changes.labelIds) edits.push(changes.changes.labelIds.length ? 'replace every label' : 'clear every label');
  if (changes.addLabelIds?.length) edits.push('add labels');
  if (changes.removeLabelIds?.length) edits.push('remove labels');
  return {
    ids: issues.map(issue => issue.id),
    summary: edits.length ? edits.join(', ') : 'No field changes chosen',
    valid: issues.length > 0 && edits.length > 0,
    destructive: changes.changes.assigneeId === null || changes.changes.labelIds !== undefined
  };
}

import { useEffect, useMemo, useState } from 'preact/hooks';
import { Button, Notice } from '../../components/ui.jsx';
import { createPlanningScope } from './planning-actions.js';
export function usePlanningAction() {
  const scope = useMemo(() => createPlanningScope(), []);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [notice, setNotice] = useState('');
  useEffect(() => () => scope.dispose(), [scope]);
  async function run(execute, success) {
    const operation = scope.begin();
    if (!operation) return null;
    setBusy(true); setError(null); setNotice('');
    try {
      const value = await execute(operation);
      if (!operation.current()) return null;
      success?.(value);
      return value;
    } catch (error) {
      if (operation.current()) setError(error);
      return null;
    } finally {
      if (operation.current()) setBusy(false);
      operation.finish();
    }
  }
  return { run, busy, error, setError, notice, setNotice, cancel: scope.cancel };
}
export function usePlanningDraft(record) {
  const [base, setBase] = useState(null);
  const [draft, setDraft] = useState(null);
  const [latest, setLatest] = useState(null);
  function load(value) { setBase(value); setDraft(structuredClone(value)); setLatest(null); }
  useEffect(() => {
    if (!record) return;
    if (!base) load(record);
    else if (base.revision !== record.revision) setLatest(record);
  }, [record]);
  return { base, draft, setDraft, latest, setLatest, load,
    keep(value) { setBase(value); setLatest(null); },
    dirty: Boolean(draft && base && JSON.stringify(draft) !== JSON.stringify(base)) };
}
export function PlanningRefresh({ busy, dirty = false, selected = false, onRefresh }) {
  const [stale, setStale] = useState(false);
  useEffect(() => {
    const mark = () => setStale(true);
    window.addEventListener('focus', mark);
    return () => window.removeEventListener('focus', mark);
  }, []);
  function refresh() {
    if (selected && !globalThis.confirm('Refresh the current view and clear its selection?')) return;
    setStale(false); onRefresh();
  }
  return <aside className="planning-refresh">
    <p role="status">{stale ? 'This view may have changed while you were away. ' : ''}Live planning updates are unavailable here; refresh to check current access and saved work.</p>
    {dirty && <Notice>Your draft is retained during refresh. Inspect and explicitly load a newer saved version before replacing it.</Notice>}
    <Button type="button" disabled={busy} onClick={refresh}>Refresh planning view</Button>
  </aside>;
}

import { useState } from 'preact/hooks';
