      <Field label="Project key" name="key" placeholder="TEAM" required minLength={2} maxLength={12} pattern="[A-Za-z][A-Za-z0-9]+" error={action.error?.details?.key} />
      <Field label="Project name" name="name" required maxLength={160} error={action.error?.details?.name} />
      <Field label="Description" error={action.error?.details?.description}><textarea name="description" rows={4} maxLength={20000} /></Field>
