export function ProjectSettings(props) { return <SettingsResource key={props.params.projectId} {...props} />; }
function SettingsResource({ api, params, navigate }) {
  const route = '/projects/' + encodeURIComponent(params.projectId);
  const result = useLoad(() => api.get(route), [route]);
  const form = usePlanningDraft(result.data?.project);
